test("landed confirmation matches the finalized signed message to simulation", async () => {
  const unsigned = Buffer.concat([Buffer.from([1]), Buffer.alloc(64), Buffer.from([1, 2, 3])]), identity = validateUnsignedTransactionBase64(unsigned.toString("base64")), signed = Buffer.from(unsigned); signed[1] = 7; const signature = "1".repeat(64), simulationReceipt = { status: "simulated", submitted: false, signed: false, genesisHash: MAINNET_GENESIS_HASH, simulationSlot: 700, messageHash: identity.messageHash }, calls = [];
  const client = { endpoint: "http://127.0.0.1:8899", call: async (method) => { calls.push(method); if (method === "getSignatureStatuses") return { value: [{ slot: 701, confirmations: null, confirmationStatus: "finalized", err: null }] }; return { slot: 701, meta: { err: null }, transaction: [signed.toString("base64"), "base64"] }; } }, receipt = await verifyFinalizedLandedTransaction(client, { signature, simulationReceipt, expectedGenesisHash: MAINNET_GENESIS_HASH, genesisHash: MAINNET_GENESIS_HASH }); assert.deepEqual({ status: receipt.status, submitted: receipt.submittedByIndexer, simulationSlot: receipt.simulationSlot, finalizedSlot: receipt.finalizedSlot }, { status: "finalized", submitted: false, simulationSlot: 700, finalizedSlot: 701 }); assert.deepEqual(calls, ["getSignatureStatuses", "getTransaction"]);
  const other = Buffer.from(signed); other[65] = 9; await assert.rejects(verifyFinalizedLandedTransaction({ endpoint: client.endpoint, call: async (method) => method === "getSignatureStatuses" ? { value: [{ slot: 701, confirmationStatus: "finalized", err: null }] } : { slot: 701, meta: { err: null }, transaction: [other.toString("base64"), "base64"] } }, { signature, simulationReceipt, expectedGenesisHash: MAINNET_GENESIS_HASH, genesisHash: MAINNET_GENESIS_HASH }), /does not match/); await assert.rejects(verifyFinalizedLandedTransaction({ endpoint: client.endpoint, call: async () => ({ value: [{ slot: 699, confirmationStatus: "confirmed", err: null }] }) }, { signature, simulationReceipt, expectedGenesisHash: MAINNET_GENESIS_HASH, genesisHash: MAINNET_GENESIS_HASH }), /not finalized/);
});

test("unsigned message inspection enforces the Solana program allowlist", async () => {
  const payer = Buffer.alloc(32), programBytes = Buffer.alloc(32, 1), encode58 = (bytes) => { const alphabet = "123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz"; let value = 0n, output = ""; for (const byte of bytes) value = value * 256n + BigInt(byte); while (value) { output = alphabet[Number(value % 58n)] + output; value /= 58n; } for (const byte of bytes) { if (byte) break; output = `1${output}`; } return output || "1"; }, programId = encode58(programBytes), message = Buffer.concat([Buffer.from([1, 0, 1, 2]), payer, programBytes, Buffer.alloc(32), Buffer.from([1, 1, 1, 0, 1, 42])]), transaction = Buffer.concat([Buffer.from([1]), Buffer.alloc(64), message]).toString("base64"), inspected = inspectUnsignedTransactionPrograms(transaction, { allowedProgramIds: [programId], requiredProgramIds: [programId] }); assert.deepEqual({ version: inspected.messageVersion, signatures: inspected.signatureCount, accounts: inspected.accountCount, instructions: inspected.instructionCount, programs: inspected.programIds }, { version: "legacy", signatures: 1, accounts: 2, instructions: 1, programs: [programId] });
  assert.throws(() => inspectUnsignedTransactionPrograms(transaction, { allowedProgramIds: ["different"] }), /outside the allowlist/); assert.throws(() => inspectUnsignedTransactionPrograms(transaction, { allowedProgramIds: [programId], requiredProgramIds: [programId, "missing"] }), /policy is invalid/);
  const receipt = await simulateUnsignedTransaction({ endpoint: "http://127.0.0.1:8899", call: async () => ({ context: { slot: 800 }, value: { err: null, logs: [], unitsConsumed: 10 } }) }, { transactionBase64: transaction, minContextSlot: 800, expectedGenesisHash: MAINNET_GENESIS_HASH, genesisHash: MAINNET_GENESIS_HASH, allowedProgramIds: [programId], requiredProgramIds: [programId] }); assert.deepEqual(receipt.programIds, [programId]); assert.equal(receipt.messageVersion, "legacy");
});

