  assert.equal(BigInt(quote.amountInRaw) + BigInt(quote.feeAmountRaw), 10_000n); assert.ok(BigInt(quote.amountOutRaw) > 0n); assert.equal(BigInt(quote.endSqrtPriceX64) > raydiumSqrtPriceX64AtTick(100), true);
