test("operational worker claims leases, retries safely, and is never auto-enabled", async () => {
  const workerId = "11111111-1111-4111-8111-111111111111", claim = claimOperationalJobSql(workerId, 300, 5); assert.match(claim, /FOR UPDATE SKIP LOCKED/); assert.match(claim, /lease_expires_at < now\(\)/); assert.match(claim, /attempts < 5/); const raw = { id: 7, job_key: "account-snapshot:11111111111111111111111111111111", job_type: "account_snapshot", payload: { schemaVersion: 1, chain: "solana-mainnet", mint: "11111111111111111111111111111111" }, attempts: 2 }, job = validateOperationalJob(raw); assert.equal(job.target, raw.payload.mint); assert.match(finishOperationalJobSql(job, workerId), /status='succeeded'.*lease_expires_at >= now\(\)/); assert.match(renewOperationalJobLeaseSql(job, workerId, 300), /lease_expires_at=now\(\)\+interval '300 seconds'.*locked_by=.*lease_expires_at >= now\(\)/); const failedSql = finishOperationalJobSql(job, workerId, "https://secret.example/?api-key=value", 5, 30); assert.match(failedSql, /interval '60 seconds'/); assert.equal(failedSql.includes("secret.example"), false); assert.throws(() => validateOperationalJob({ ...raw, payload: { ...raw.payload, mint: "not-base58" } }), /invalid operational job target/);
  const queries = [], result = await runOperationalJobCycle({ workerId, query: async (sql) => { queries.push(sql); return queries.length === 1 ? JSON.stringify(raw) : "7"; }, execute: async (claimed) => assert.deepEqual({ type: claimed.type, target: claimed.target }, { type: "account_snapshot", target: raw.payload.mint }) }); assert.deepEqual(result, { claimed: true, succeeded: true, id: 7, type: "account_snapshot" }); assert.match(queries[1], /status='succeeded'/);
  const orcaRaw = { ...raw, job_key: "orca-pool-snapshot:11111111111111111111111111111111", job_type: "orca_pool_snapshot", payload: { schemaVersion: 1, chain: "solana-mainnet", pool: "11111111111111111111111111111111" } }; assert.deepEqual(validateOperationalJob(orcaRaw), { id: 7, attempts: 2, type: "orca_pool_snapshot", target: orcaRaw.payload.pool });
  const retryQueries = [], retry = await runOperationalJobCycle({ workerId, query: async (sql) => { retryQueries.push(sql); return retryQueries.length === 1 ? JSON.stringify(raw) : "7"; }, execute: async () => { throw new Error("token=private https://provider.invalid/path"); } }); assert.equal(retry.succeeded, false); assert.equal(retry.error.includes("private"), false); assert.match(retryQueries[1], /status='pending'/); assert.equal(retryQueries[1].includes("provider.invalid"), false); await assert.rejects(runOperationalJobCycle({ workerId, query: async (sql) => sql.includes("WITH recovered") ? JSON.stringify(raw) : "", execute: async () => {} }), /lease was lost/);
  let renew; const renewalQueries = [], renewed = await runOperationalJobCycle({ workerId, query: async (sql) => { renewalQueries.push(sql); return renewalQueries.length === 1 ? JSON.stringify(raw) : "7"; }, schedule: (callback, delay) => { assert.equal(delay, 100_000); renew = callback; return { unref() {} }; }, cancel: () => {}, execute: async () => { await renew(); } }); assert.equal(renewed.succeeded, true); assert.equal(renewalQueries.length, 3); assert.match(renewalQueries[1], /lease_expires_at=now\(\)\+interval/); await assert.rejects(runOperationalJobCycle({ workerId, query: async (sql) => sql.includes("WITH recovered") ? JSON.stringify(raw) : "", schedule: (callback) => { renew = callback; return {}; }, cancel: () => {}, execute: async () => { await renew(); } }), /lease was lost during execution/);
  const service = await fs.readFile(path.join(rootDir, "validator/solana-indexer-operational-worker.service"), "utf8"), timer = await fs.readFile(path.join(rootDir, "validator/solana-indexer-operational-worker.timer"), "utf8"), installer = await fs.readFile(path.join(rootDir, "validator/install-indexer-services.sh"), "utf8"); assert.match(service, /npm run work:operational/); assert.match(service, /TimeoutStartSec=1h/); assert.match(service, /NoNewPrivileges=true/); assert.match(service, /ReadWritePaths=\/home\/sol\/solana-indexer\/data/); assert.match(timer, /OnUnitActiveSec=1min/); assert.match(installer, /solana-indexer-operational-worker\.timer/); assert.doesNotMatch(installer, /^systemctl enable --now/m);
});

