test("warehouse sync is ordered, retry-safe, and checkpoints only after both sinks", async () => {
  const state = { eventSequence: 3, events: [{ sequence: 1, type: "block_indexed", slot: 10, blockTime: 1_700_000_000, blockhash: "a", provenance: { commitment: "confirmed" } }, { sequence: 2, type: "block_finalized", slot: 10, blockTime: 1_700_000_000, blockhash: "a", provenance: { commitment: "finalized" } }, { sequence: 3, type: "block_replaced", slot: 11, blockTime: 1_700_000_001, blockhash: "b", provenance: { commitment: "finalized" } }] };
  const batch = compileWarehouseBatch(state, { lastSequence: 1 }); assert.deepEqual({ from: batch.fromSequence, to: batch.toSequence, events: batch.events.map((row) => row.sequence) }, { from: 2, to: 3, events: [2, 3] }); assert.equal(batch.events[0].commitment, "finalized"); assert.match(checkpointSql(3), /warehouse-canonical-events.*5eykt4UsFv8P8NJdTREpY1vzqKqZKvdpKuc147dw2N9d.*'3'/s);
  assert.throws(() => compileWarehouseBatch({ eventSequence: 3, events: state.events.slice(1) }, { lastSequence: 0 }), /older than retained replay history/); assert.throws(() => compileWarehouseBatch(state, { lastSequence: 4 }), /ahead of index/); assert.throws(() => compileWarehouseBatch({ eventSequence: 3, events: [state.events[0], state.events[2]] }, { lastSequence: 0 }), /sequence gap/);
  assert.throws(() => compileWarehouseBatch({ eventSequence: 1, events: [{ ...state.events[0], provenance: { commitment: "unknown" } }] }), /invalid warehouse event/);
  const calls = [], spawnProcess = (command, args) => { const listeners = {}, stderr = { on() {} }, stdin = { end(input) { calls.push({ command, args, input }); queueMicrotask(() => listeners.close(0)); } }; return { stderr, stdin, on(name, handler) { listeners[name] = handler; } }; }; const result = await syncWarehouseBatch(batch, spawnProcess); assert.deepEqual(result, { synced: 2, sequence: 3 }); assert.deepEqual(calls.map((row) => row.command), ["clickhouse-client", "psql"]); assert.match(calls[0].input, /"sequence":2/); assert.equal(calls.some((row) => row.input.includes("password")), false);
  const sinks = validateWarehouseSinkSequences(3, { clickhouse: "3\n", postgres: "3", redis: "3" }); assert.deepEqual(sinks, { clickhouse: 3, postgres: 3, redis: 3 }); assert.throws(() => validateWarehouseSinkSequences(3, { clickhouse: "2", postgres: "3", redis: "3" }), /clickhouse warehouse sequence mismatch/); assert.throws(() => validateWarehouseSinkSequences(3, { clickhouse: "3", postgres: "", redis: "3" }), /postgres warehouse sequence unavailable/);
  const probeCalls = [], probeSpawn = (command, args) => { probeCalls.push({ command, args }); const listeners = {}, stdout = { on(name, handler) { if (name === "data") queueMicrotask(() => { handler(Buffer.from("3\n")); listeners.close(0); }); } }, stderr = { on() {} }; return { stdout, stderr, on(name, handler) { listeners[name] = handler; } }; }; assert.deepEqual(await probeWarehouseSinks(3, probeSpawn, {}), sinks); assert.deepEqual(probeCalls.map((row) => row.command).sort(), ["clickhouse-client", "psql", "redis-cli"]); assert.match(probeCalls.find((row) => row.command === "psql").args.at(-1), /warehouse-canonical-events/); assert.deepEqual(probeCalls.find((row) => row.command === "redis-cli").args, ["--raw", "GET", "terminal_dex:hot:current"]);
  const reconciliation = validateWarehouseReconciliation({ sequence: 3, events: 3, instructions: 1, swaps: 2, balanceChanges: 4, deadLetters: 0, tokens: 5, pools: 6 }, { clickhouse: "3\n1\n2\n4\n0", postgres: "3\n5", redis: "3\n6\n5" }); assert.equal(reconciliation.verified, true); assert.throws(() => validateWarehouseReconciliation(reconciliation, { clickhouse: "3\n1\n1\n4\n0", postgres: "3\n5", redis: "3\n6\n5" }), /mismatch/);
  const outputs = { "clickhouse-client": "3\n1\n2\n4\n0", psql: "3\n5", "redis-cli": "3\n6\n5" }, reconciliationCalls = [], reconciliationSpawn = (command, args) => { reconciliationCalls.push({ command, args }); const listeners = {}, stdout = { on(name, handler) { if (name === "data") queueMicrotask(() => { handler(Buffer.from(outputs[command])); listeners.close(0); }); } }, stderr = { on() {} }; return { stdout, stderr, on(name, handler) { listeners[name] = handler; } }; }; assert.deepEqual(await probeWarehouseReconciliation(reconciliation, reconciliationSpawn, {}), reconciliation); assert.match(reconciliationCalls.find((row) => row.command === "clickhouse-client").args.at(-1), /uniqExact\(event_id\)/);
  const root = await fs.mkdtemp(path.join(os.tmpdir(), "warehouse-checkpoint-")), filename = path.join(root, "nested", "checkpoint.json"); await writeWarehouseCheckpoint(filename, 3, sinks, reconciliation); const persisted = JSON.parse(await fs.readFile(filename, "utf8")); assert.deepEqual({ schemaVersion: persisted.schemaVersion, consumer: persisted.consumer, lastSequence: persisted.lastSequence, sinks: persisted.sinks, reconciliation: persisted.reconciliation }, { schemaVersion: 1, consumer: "warehouse-canonical-events", lastSequence: 3, sinks, reconciliation }); await assert.rejects(writeWarehouseCheckpoint(filename, 3, sinks), /reconciliation/);
});

